/**
 * Question builder actions for evaluations.
 * @module     local_sentientia_evaluation/question_actions
 * @copyright  2026 Airpay Payment Services
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("local_sentientia_evaluation/question_actions", [
    "core_form/modalform",
    "core/str",
    "core/notification",
    "core/ajax"
], function(ModalForm, Str, Notification, Ajax) {
    "use strict";

    var openQuestionForm = function(questionid, evaluationid, returnFocus) {
        var titleKey = (questionid === 0) ? "addquestion" : "editquestion";
        Str.get_string(titleKey, "local_sentientia_evaluation").then(function(title) {
            var modalForm = new ModalForm({
                formClass: "local_sentientia_evaluation\\form\\edit_question",
                args: {questionid: questionid, evaluationid: evaluationid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || "Saved.";
                Notification.addNotification({message: message, type: "success"});
                window.location.reload();
            });
            modalForm.show();
            return null;
        }).catch(Notification.exception);
    };

    var confirmDelete = function(questionid, returnFocus) {
        Promise.all([
            Str.get_string("deletequestion", "local_sentientia_evaluation"),
            Str.get_string("confirmdeletequestion", "local_sentientia_evaluation"),
            Str.get_string("delete", "core"),
            Str.get_string("questiondeleted", "local_sentientia_evaluation")
        ]).then(function(strings) {
            Notification.deleteCancelPromise(strings[0], strings[1], strings[2], returnFocus).then(function() {
                Ajax.call([{methodname: "local_sentientia_evaluation_delete_question",
                            args: {questionid: questionid}}])[0]
                    .then(function() {
                        Notification.addNotification({message: strings[3], type: "success"});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
                return true;
            }, function() { return null; });
            return null;
        }).catch(Notification.exception);
    };

    var saveOrder = function(root) {
        var evaluationid = parseInt(root.dataset.evaluationid || "0", 10);
        var list = root.querySelector("#airpay-question-list");
        if (!list) return;

        var items = list.querySelectorAll(".question-item");
        var ids = [];
        for (var i = 0; i < items.length; i++) {
            var id = parseInt(items[i].dataset.questionid, 10);
            if (!isNaN(id) && id > 0) ids.push(id);
        }
        if (ids.length === 0) return;

        Ajax.call([{
            methodname: "local_sentientia_evaluation_reorder_questions",
            args: {evaluationid: evaluationid, questionids: ids}
        }])[0].then(function() {
            Str.get_string("orderupdated", "local_sentientia_evaluation").then(function(msg) {
                Notification.addNotification({message: msg, type: "success"});
                items.forEach(function(el, idx) {
                    var pos = el.querySelector(".question-position");
                    if (pos) pos.textContent = idx + 1;
                });
                return null;
            }).catch(Notification.exception);
            return null;
        }).catch(Notification.exception);
    };

    var wireDragDrop = function(root) {
        var list = root.querySelector("#airpay-question-list");
        if (!list) return;

        var draggedEl = null;

        list.addEventListener("dragstart", function(e) {
            var item = e.target.closest(".question-item");
            if (!item) return;
            draggedEl = item;
            item.classList.add("dragging");
            e.dataTransfer.effectAllowed = "move";
            e.dataTransfer.setData("text/plain", item.dataset.questionid);
        });

        list.addEventListener("dragend", function(e) {
            var item = e.target.closest(".question-item");
            if (item) item.classList.remove("dragging");
            list.querySelectorAll(".drag-over").forEach(function(el) {
                el.classList.remove("drag-over");
            });
            draggedEl = null;
        });

        list.addEventListener("dragover", function(e) {
            e.preventDefault();
            e.dataTransfer.dropEffect = "move";
            var target = e.target.closest(".question-item");
            if (!target || target === draggedEl) return;
            list.querySelectorAll(".drag-over").forEach(function(el) {
                el.classList.remove("drag-over");
            });
            target.classList.add("drag-over");
        });

        list.addEventListener("drop", function(e) {
            e.preventDefault();
            var target = e.target.closest(".question-item");
            if (!target || !draggedEl || target === draggedEl) return;

            var targetRect = target.getBoundingClientRect();
            var insertAfter = (e.clientY - targetRect.top) > (targetRect.height / 2);
            if (insertAfter) {
                target.parentNode.insertBefore(draggedEl, target.nextSibling);
            } else {
                target.parentNode.insertBefore(draggedEl, target);
            }
            target.classList.remove("drag-over");

            saveOrder(root);
        });
    };

    var handleClick = function(event) {
        var trigger = event.target.closest("[data-action]");
        if (!trigger) return;
        var action = trigger.dataset.action;
        var root = document.querySelector('[data-region="airpay-eval-questions"]');
        var evaluationid = parseInt((root && root.dataset.evaluationid) || "0", 10);
        var questionid = parseInt(trigger.dataset.questionid || "0", 10);

        switch (action) {
            case "add-question":
                event.preventDefault();
                openQuestionForm(0, evaluationid, trigger);
                break;
            case "edit-question":
                event.preventDefault();
                openQuestionForm(questionid, evaluationid, trigger);
                break;
            case "delete-question":
                event.preventDefault();
                confirmDelete(questionid, trigger);
                break;
        }
    };

    return {
        init: function() {
            var root = document.querySelector('[data-region="airpay-eval-questions"]');
            if (!root || root.dataset.airpayQuestionsInit === "1") return;
            root.dataset.airpayQuestionsInit = "1";
            root.addEventListener("click", handleClick);
            wireDragDrop(root);
        }
    };
});
